167	export async function listUsers(search?: string): Promise<ProfileRow[]> {
168	  const supabase = await createClient();
169	  let query = supabase.from("profiles").select("*");
170	  if (search && search.trim()) {
171	    const term = `%${search.trim()}%`;
172	    query = query.or(`full_name.ilike.${term},email.ilike.${term}`);
173	  }
174	  const { data, error } = await query
175	    .order("created_at", { ascending: false })
176	    .limit(100);
177	  if (error) throw error;
178	  return data ?? [];
179	}
